<?php
namespace Tests\Feature\InternalGames;
use Tests\TestCase;
use Tests\Support\BlackjackFixture;
use App\Services\InternalGames\{BlackjackService,InternalGameSessionService};
use App\Models\{CmsGame,InternalGameRound,CmsUserTransaction,WalletLedgerEntry,InternalGameSession};
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\DB;
class BlackjackRoundFlowTest extends TestCase {
 use DatabaseTransactions,BlackjackFixture;
 protected function setUp():void{parent::setUp();$this->setupBlackjack();}
 public function test_round_progression_replay_stale_double_after_hit_and_resume():void{
  $this->vector();$s=$this->openBlackjack();$svc=app(BlackjackService::class);$start=$svc->startRound($s->session_token,$this->player,10,'bj-start-1');$this->assertSame('awaiting_player_action',$start['status']);$this->assertSame(['hit','stand','double'],$start['allowedActions']);$this->assertSame(490.0,$start['balance']);$this->assertTrue($start['dealer']['cards'][1]['hidden']);$this->assertArrayNotHasKey('dealer_cards',$start['actionTimeline'][0]);$this->assertStringNotContainsString('remainingDeck',json_encode($svc->playPayload($s)));
  $hit=$svc->action($s->session_token,$this->player,$start['roundId'],'hit','bj-hit-1',1);$this->assertSame(2,$hit['roundVersion']);$this->assertSame(['hit','stand'],$hit['allowedActions']);$this->assertEquals($hit,$svc->action($s->session_token,$this->player,$start['roundId'],'hit','bj-hit-1',1));$this->rejectBlackjack(fn()=>$svc->action($s->session_token,$this->player,$start['roundId'],'stand','bj-stale-1',1),'BLACKJACK_STALE_ACTION');$this->rejectBlackjack(fn()=>$svc->action($s->session_token,$this->player,$start['roundId'],'double','bj-invalid-double',2),'BLACKJACK_ACTION_REJECTED');$this->assertSame(2,$svc->playPayload($s)['currentRound']['roundVersion']);
  $settled=$svc->action($s->session_token,$this->player,$start['roundId'],'stand','bj-stand-1',2);$this->assertSame('win',$settled['outcome']);$this->assertSame(20.0,$settled['payoutTotal']);$this->assertSame(510.0,$settled['balance']);$this->assertCount(1,$svc->playPayload($s)['history']);$this->assertNull($svc->playPayload($s)['currentRound']);$this->assertSame(2,CmsUserTransaction::count());$this->reconcileBlackjack();
 }
 public function test_create_replay_conflict_active_round_and_insufficient_double_no_second_debit():void{
  $this->vector();$s=$this->openBlackjack();$svc=app(BlackjackService::class);$start=$svc->startRound($s->session_token,$this->player,5,'bj-start-tight');$before=$this->financeHash();$this->assertEquals($start,$svc->startRound($s->session_token,$this->player,5,'bj-start-tight'));$this->rejectBlackjack(fn()=>$svc->startRound($s->session_token,$this->player,25,'bj-start-tight'),'BLACKJACK_REPLAY_PAYLOAD_MISMATCH');$this->rejectBlackjack(fn()=>$svc->startRound($s->session_token,$this->player,5,'bj-second-open'),'BLACKJACK_ACTIVE_ROUND_EXISTS');$this->assertSame($before,$this->financeHash());
  app(\App\Services\Finance\ManualFinanceOverrideService::class)->execute(['operation_id'=>'remove-remaining','customer_id'=>$this->player->id,'wallet_account_id'=>$this->wallet->id,'currency'=>'TRY','economic_action'=>'manual_debit','external_resolution'=>'manual_operator_decision','amount'=>'495.00','reason'=>'Synthetic insufficient-double case'],$this->operator);$before=$this->financeHash();$this->rejectBlackjack(fn()=>$svc->action($s->session_token,$this->player,$start['roundId'],'double','bj-double-tight',1),'BLACKJACK_INSUFFICIENT_FUNDS');$this->assertSame($before,$this->financeHash());$this->assertSame(1,CmsUserTransaction::count());$this->reconcileBlackjack();
 }
 public function test_double_has_two_debits_and_one_payout_chain_and_replay():void{
  $this->vector(['9H','2S'],['10C','7D'],['10D']);$s=$this->openBlackjack();$svc=app(BlackjackService::class);$start=$svc->startRound($s->session_token,$this->player,10,'bj-start-double');$double=$svc->action($s->session_token,$this->player,$start['roundId'],'double','bj-double-1',1);$this->assertSame(20.0,$double['totalStake']);$this->assertSame(40.0,$double['payoutTotal']);$this->assertSame(520.0,$double['balance']);$before=$this->financeHash();$this->assertEquals($double,$svc->action($s->session_token,$this->player,$start['roundId'],'double','bj-double-1',1));$this->assertSame($before,$this->financeHash());$this->assertSame(3,CmsUserTransaction::count());$this->assertSame(1,CmsUserTransaction::where('event_type','internal_blackjack_double_bet')->count());$this->reconcileBlackjack();
 }
 public static function payouts():array{$cases=[];foreach(['blackjack-classic','blackjack-salon']as $code)foreach([false,true]as $demo)foreach(['win','loss','push','blackjack','dealer_natural']as $outcome)$cases[$code.($demo?'-demo':'-real').'-'.$outcome]=[$code,$demo,$outcome];return $cases;}
 #[\PHPUnit\Framework\Attributes\DataProvider('payouts')]
 public function test_both_tables_both_modes_win_loss_push_natural_payout(string $code,bool $demo,string $outcome):void{
  [$p,$d,$expected]=match($outcome){'win'=>[['10H','QH'],['10C','7D'],50.0],'loss'=>[['9H','6S'],['10C','9D'],0.0],'push'=>[['10H','QH'],['10C','QD'],25.0],'blackjack'=>[['AH','KD'],['9C','7S'],62.5],'dealer_natural'=>[['9H','8S'],['AC','KD'],0.0]};$this->vector($p,$d,['2D']);$s=$this->openBlackjack($code,$demo);$svc=app(BlackjackService::class);$before=$this->financeHash();$r=$svc->startRound($s->session_token,$this->player,25,'payout-start');if($r['phase']==='player_turn')$r=$svc->action($s->session_token,$this->player,$r['roundId'],'stand','payout-stand',1);$this->assertSame($expected,$r['payoutTotal']);$this->assertSame(500.0-25+$expected,$r['balance']);$this->assertSame($r['balance'],(float)$svc->playPayload($s)['balance']);$this->assertSame('resolved',$r['phase']);$this->assertNotSame($before,$this->financeHash());$this->assertSame($outcome==='push'?'internal_blackjack_push':($expected>0?'internal_blackjack_win':'internal_blackjack_bet'),CmsUserTransaction::latest('id')->value('event_type'));$this->reconcileBlackjack();
 }
 public function test_demo_labeled_double_uses_canonical_debit_and_rejects_insufficient_funds():void{
  $this->vector(['9H','2S'],['10C','7D'],['10D']);$s=$this->openBlackjack('blackjack-salon',true);$svc=app(BlackjackService::class);$r=$svc->startRound($s->session_token,$this->player,25,'demo-double-start');$r=$svc->action($s->session_token,$this->player,$r['roundId'],'double','demo-double-action',1);$this->assertSame(550.0,$r['balance']);$this->assertSame(550.0,(float)$svc->playPayload($s)['balance']);app(\App\Services\Finance\ManualFinanceOverrideService::class)->execute(['operation_id'=>'demo-label-drain','customer_id'=>$this->player->id,'wallet_account_id'=>$this->wallet->id,'currency'=>'TRY','economic_action'=>'manual_debit','external_resolution'=>'manual_operator_decision','amount'=>'525.00','reason'=>'Synthetic double rejection'],$this->operator);$s=$this->openBlackjack('blackjack-salon',true);$r=$svc->startRound($s->session_token,$this->player,25,'demo-tight-start');$this->rejectBlackjack(fn()=>$svc->action($s->session_token,$this->player,$r['roundId'],'double','demo-tight-double',1),'BLACKJACK_INSUFFICIENT_FUNDS');$this->assertSame(0.0,(float)$svc->playPayload($s)['balance']);
 }
 public function test_expired_open_hand_is_resumed_with_rotated_token_and_same_wallet_no_new_debit():void{
  $this->vector();$s=$this->openBlackjack();$svc=app(BlackjackService::class);$r=$svc->startRound($s->session_token,$this->player,10,'resume-start');$old=$s->session_token;$payload=$s->launch_payload;$s->update(['expires_at'=>now()->subMinute()]);try{app(InternalGameSessionService::class)->resolvePlayableSession($old,$this->player);$this->fail('Expired');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(410,$e->getStatusCode());}$before=$this->financeHash();$resumed=$this->openBlackjack();$this->assertSame($s->id,$resumed->id);$this->assertNotSame($old,$resumed->session_token);$this->assertSame($payload,$resumed->launch_payload);$this->assertSame($before,$this->financeHash());$this->assertSame($resumed->session_token,$this->openBlackjack()->session_token);$this->assertContains('open_internal_game_round',array_column(app(\App\Services\Wallet\WalletChangeGuardService::class)->evaluate($this->player)['reasons'],'code'));$svc->action($resumed->session_token,$this->player,$r['roundId'],'stand','resume-stand',1);$this->reconcileBlackjack();
 }
 public function test_expired_empty_or_settled_and_closed_sessions_are_not_revived():void{
  $this->vector();$s=$this->openBlackjack();$s->update(['expires_at'=>now()->subMinute()]);$fresh=$this->openBlackjack();$this->assertNotSame($s->id,$fresh->id);$r=app(BlackjackService::class)->startRound($fresh->session_token,$this->player,10,'closed-start');app(BlackjackService::class)->action($fresh->session_token,$this->player,$r['roundId'],'stand','closed-stand',1);$fresh->update(['expires_at'=>now()->subMinute()]);$this->assertNotSame($fresh->id,$this->openBlackjack()->id);
 }
 public function test_double_push_returns_total_stake_once_and_refund_is_rejected():void {
  $this->vector(['9H','2S'],['10C','KD'],['9D']);$s=$this->openBlackjack();$svc=app(BlackjackService::class);$r=$svc->startRound($s->session_token,$this->player,10,'double-push-start');$r=$svc->action($s->session_token,$this->player,$r['roundId'],'double','double-push-action',1);$this->assertSame('push',$r['outcome']);$this->assertSame(20.0,$r['payoutTotal']);$this->assertSame('500.00000000',$this->wallet->fresh()->available_balance);$before=$this->financeHash();$this->rejectBlackjack(fn()=>$svc->refund($r['roundId'],'push-refund-rejected',$this->operator),'BLACKJACK_REFUND_REJECTED');$this->assertSame($before,$this->financeHash());$this->reconcileBlackjack();
 }
 public function test_original_engine_dealer_soft17_rule_is_preserved():void {
  $engine=new \App\Services\InternalGames\BlackjackEngine;$d=config('internal_games.games.blackjack-classic');$state=\Tests\Support\BlackjackVectors::initial($d,10,['9H','9S'],['AC','6D'],['4D']);$this->assertSame('win',$engine->applyAction($state,'stand')['outcome']);$d['dealer_hits_soft_17']=true;$state=\Tests\Support\BlackjackVectors::initial($d,10,['9H','9S'],['AC','6D'],['4D']);$this->assertSame('loss',$engine->applyAction($state,'stand')['outcome']);
 }

}
